import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static long sumOfMaximums(long[] a) {
        int len = a.length;
        long total = 0;
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i = 0; i <= len; i++) {
            while (!stack.isEmpty() && (i == len || a[stack.peek()] < a[i])) {
                int j = stack.pop();
                int left = stack.isEmpty() ? -1 : stack.peek();
                total += a[j] * (j - left) * (i - j);
            }
            stack.push(i);
        }
        return total;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());

        long[] negated = new long[a.length];
        for (int i = 0; i < a.length; i++) negated[i] = -a[i];
        System.out.println(sumOfMaximums(a) + sumOfMaximums(negated));
    }
}
